import {CAMPAIGN_STATUS,TASK_STATUS,cleanCampaign,updateCampaign,filterDirectory,radarEvents,campaignCalendar} from './campaigns.js?v=0.9.0';
import {PROOF_TYPES,BRIEF_STAGES,cleanBrief,cleanHunterProfile,addProof,briefReadiness,compass,compareProofs,researchPack} from './hunter.js?v=0.9.0';
import {QUESTS,BADGES,badgeEarned,unlockBadges,QUIZ,RESOURCES,BLUEPRINTS,GLOSSARY,dayKey,xpTotal,levelInfo,streak,claimQuest} from './rewards.js?v=0.9.0';
import {PRIMARY_NAV,resolveRoute,primaryRoute} from './navigation.js?v=0.9.0';
import {CLAIM_STAGES,TRUST_BANDS,cleanDossier,cleanReview,sourceSignals} from './exhibits.js?v=0.9.0';
import {projects as demos} from './catalog.js?v=0.9.0';
import {createInvitePayload} from './referral.js?v=0.9.0';
import {normalize,cleanProject,backup,mergeBackup,icsEvent} from './model.js?v=0.9.0';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let raw;try{raw=JSON.parse(localStorage.getItem('airdrop-museum-v1'))||{}}catch{raw={}}let state;try{state=normalize(raw,demos)}catch{state=normalize({},demos)}
const nav=PRIMARY_NAV;
const labels={watching:'Pantauan',active:'Berjalan',completed:'Selesai',archived:'Diarsipkan'};
let serverInfo=null,cloudRevision=null,syncBusy=false,remoteXP=null,rewardBusy=false,lastQuizAnswers=null,missionTab='quests';
let pendingInvite='';try{const code=new URL(location.href).searchParams.get('ref');if(/^[a-f0-9]{16}$/.test(code||''))sessionStorage.setItem('museum-pending-invite',code);pendingInvite=sessionStorage.getItem('museum-pending-invite')||''}catch{}
let profileTab='overview',detailTab='overview',detailDraft=null,portfolioView='board';
let directoryFilters={status:'all',kind:'all',difficulty:'all',cost:'all'};
let page='home',query='',category='All',chain='All',sort='featured',mode='all',month=new Date(new Date().getFullYear(),new Date().getMonth(),1),openId=null;
const all=()=>[...demos,...state.custom],project=id=>all().find(p=>p.id===id),rec=p=>state.records[p.id],done=p=>p.tasks.filter((_,i)=>state.done[p.id+':'+i]).length,total=()=>all().reduce((n,p)=>n+done(p),0),today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`},money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(n);
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function persist(text){state.progress=unlockBadges(state);if(text&&/Updated checklist|Saved research|Created |Added local review|Completed learning|Saved proof trail|Saved bounty brief/.test(text)){const key=dayKey();if(!state.progress.days.includes(key))state.progress.days.push(key)}if(text)state.history.unshift({at:new Date().toISOString(),text});state.history=state.history.slice(0,100);try{localStorage.setItem('airdrop-museum-v1',JSON.stringify(state))}catch{toast('Penyimpanan tidak tersedia. Ekspor backup sebelum menutup aplikasi.')}}
function navigate(id){page=resolveRoute(id);if(id==='referral')profileTab='invite';query='';category=chain='All';mode='all';directoryFilters={status:'all',kind:'all',difficulty:'all',cost:'all'};location.hash=page;render();window.scrollTo(0,0)}
function intro(title,desc,action=''){return `<div class="intro"><div><span class="eyeline">AIRDROP MUSEUM <span class="tiny-dot"></span> RESEARCH COLLECTION</span><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
const empty=(text,button='')=>`<div class="empty">${text}${button}</div>`;
function stats(){const tracked=all().filter(p=>state.saved.includes(p.id)&&rec(p).status!=='archived');return `<div class="stats">${[['layers',tracked.length,'Dalam portofolio','Exhibit yang Anda ikuti'],['activity',tracked.filter(p=>rec(p).status==='active').length,'Riset berjalan','Pekerjaan yang sedang aktif'],['check',total(),'Tugas selesai','Progres yang dicatat sendiri'],['calendar',tracked.filter(p=>rec(p).due&&rec(p).due>=today()).length,'Tenggat mendatang','Target riset pribadi']].map(([i,n,l,sub])=>`<div class="stat"><div class="stat-top"><span class="stat-icon">${icon(i)}</span><small>${l}</small></div><b>${n.toLocaleString('id-ID')}</b><span class="stat-caption">${sub}</span></div>`).join('')}</div>`}
function row(p){const r=rec(p);return `<button class="project-row" data-open="${esc(p.id)}"><span class="row-symbol">${p.symbol}</span><span><b>${esc(p.name)}</b><small>${esc(p.chain)} · ${p.custom?'Personal project':'Demo'} · ${labels[r.status]}</small></span><span class="row-meta">${done(p)}/${p.tasks.length}<small>${r.due||'No deadline'}</small></span><span>↗</span></button>`}
function activity(){return state.history.length?`<ol class="activity">${state.history.slice(0,8).map(h=>`<li><span>${esc(h.text)}</span><time>${esc(new Date(h.at).toLocaleString('id-ID'))}</time></li>`).join('')}</ol>`:empty('Aktivitas riset Anda akan muncul di sini.')}
function card(p){const saved=state.saved.includes(p.id),r=rec(p),evidence=['audit','team','treasury','chainEvidence','risks'].filter(k=>r.dossier[k]).length;return `<article class="card"><div class="card-art art-${all().indexOf(p)%4}"><span class="exhibit-no">EXHIBIT / ${String(all().indexOf(p)+1).padStart(3,'0')}</span><button class="save ${saved?'saved':''}" data-save="${esc(p.id)}" aria-label="${saved?'Untrack':'Track'} ${esc(p.name)}" aria-pressed="${saved}">${icon('bookmark')}</button><div class="art-orbit"></div><div class="art-plinth"><span>${p.symbol}</span></div><span class="art-caption">${esc(p.chain)} ECOSYSTEM</span></div><div class="card-body"><div class="card-overline"><span class="source-badge ${p.custom?'personal':''}">${p.custom?'Proyek pribadi':'Contoh fiktif'}</span><span>${esc(p.category)}</span></div><h3>${esc(p.name)}</h3><p>${esc(p.desc||'Tambahkan konteks dan bukti untuk melengkapi riset exhibit ini.')}</p>${campaignCard(p)}<div class="card-evidence"><div><span class="evidence-dot ${evidence?'filled':''}"></span><span>${evidence}/5 catatan bukti</span></div><span>Belum diverifikasi</span></div>${saved?`<div class="card-tracking"><span>${labels[r.status]}</span><span>${done(p)}/${p.tasks.length} tugas</span><div class="progress"><span style="width:${done(p)/p.tasks.length*100}%"></span></div></div>`:''}<div class="card-bottom"><span class="chain-label">${icon('globe')}${esc(p.chain)}</span><button class="text-btn" data-open="${esc(p.id)}">Buka exhibit ${icon('arrow')}</button></div></div></article>`}
function discover(){return intro('Jelajahi koleksi.','Satu tempat untuk menelaah konteks, sumber, dan jejak sebuah airdrop.',`<button class="primary" id="add-project">${icon('plus')} Tambah exhibit</button>`)+galleryTabs('explore')+`<div class="gallery-overview"><div>${icon('compass')}<span><b>${all().length} exhibit</b><small>Seluruh koleksi tetap terbuka</small></span></div><div>${icon('globe')}<span><b>${new Set(all().map(p=>p.chain)).size} ekosistem</b><small>Jelajahi lintas jaringan</small></span></div><div>${icon('shield')}<span><b>Berbasis bukti</b><small>Skor publik belum tersedia</small></span></div></div><section class="directory-tools"><div class="toolbar"><label class="search">${icon('search')}<input id="search" type="search" aria-label="Cari proyek" placeholder="Cari nama proyek, jaringan, atau kategori…"></label><select id="chain" aria-label="Filter chain"><option value="All">Semua jaringan</option>${[...new Set(all().map(p=>p.chain))].map(c=>`<option>${esc(c)}</option>`).join('')}</select><select id="mode" aria-label="Sumber proyek"><option value="all">Semua sumber</option><option value="personal">Proyek pribadi</option><option value="demo">Contoh fiktif</option></select><select id="sort" aria-label="Urutan"><option value="featured">Urutan koleksi</option><option value="name">Nama A–Z</option><option value="deadline">Tenggat kampanye terdekat</option><option value="cost">Estimasi gas terendah</option></select></div>${directoryFilterUI()}<div class="filters">${['All','Testnet','DeFi','GameFi','Layer 2','RWA','Gaming','AI','Infra','NFT'].map(c=>`<button class="chip ${c===category?'active':''}" data-category="${c}" aria-pressed="${c===category}">${c==='All'?'Semua kategori':c}</button>`).join('')}</div></section><div class="section-title"><h2>Direktori exhibit</h2><small id="count" aria-live="polite" aria-atomic="true"></small></div><div class="grid" id="project-grid"></div><div class="collection-disclosure">${icon('info')}<p>Semua exhibit bertanda contoh fiktif adalah data demonstrasi, bukan kampanye airdrop nyata. Catatan bukti pribadi bukan verifikasi independen.</p></div>`}
function updateGrid(){const list=filterDirectory(all(),state,{...directoryFilters,sort}).filter(p=>(category==='All'||p.category===category)&&(chain==='All'||p.chain===chain)&&(mode==='all'||(mode==='personal'?p.custom:!p.custom))&&[p.name,p.chain,p.category].join(' ').toLowerCase().includes(query.toLowerCase()));if(sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name));$('#project-grid').innerHTML=list.length?list.map(card).join(''):empty('Tidak ada proyek yang cocok. Coba filter lain.');$('#count').textContent=list.length+' exhibit';document.querySelectorAll('[data-category]').forEach(el=>{el.classList.toggle('active',el.dataset.category===category);el.setAttribute('aria-pressed',el.dataset.category===category)})}
function portfolioBody(){const tracked=all().filter(p=>state.saved.includes(p.id)&&rec(p).status!=='archived');return intro('Portofolio riset.','Kelola partisipasi, jadwal, dan hasil dalam satu alur kerja.',`<button class="primary" data-nav="explore">${icon('plus')} Temukan exhibit</button>`)+portfolioTabs('workspace')+`<div class="portfolio-summary"><div><b>${tracked.length}</b><span>exhibit diikuti</span></div><div><b>${tracked.filter(p=>rec(p).status==='active').length}</b><span>riset berjalan</span></div><div><b>${tracked.filter(p=>rec(p).status==='completed').length}</b><span>riset selesai</span></div><div class="view-switch" aria-label="Tampilan portofolio"><button data-view="board" class="${portfolioView==='board'?'active':''}" aria-pressed="${portfolioView==='board'}">${icon('board')} Board</button><button data-view="list" class="${portfolioView==='list'?'active':''}" aria-pressed="${portfolioView==='list'}">${icon('list')} Daftar</button></div></div>${!tracked.length?`<section class="panel full-empty"><div class="empty-illustration">${icon('layers')}</div><span class="eyeline">YOUR COLLECTION STARTS HERE</span><h2>Riset yang tersusun. Keputusan yang lebih jelas.</h2><p>Simpan exhibit dari Jelajahi untuk mulai menyusun checklist, catatan bukti, dan tenggat pribadi.</p><button class="primary" data-nav="explore">Jelajahi exhibit ${icon('arrow')}</button></section>`:portfolioView==='list'?`<section class="panel portfolio-list"><div class="section-title"><h2>Semua exhibit diikuti</h2><small>${tracked.length} exhibit</small></div>${tracked.map(row).join('')}</section>`:`<div class="kanban">${['watching','active','completed'].map(status=>`<section class="lane lane-${status}"><div class="lane-heading"><span class="lane-dot"></span><h3>${labels[status]}</h3><small>${tracked.filter(p=>rec(p).status===status).length}</small></div>${tracked.filter(p=>rec(p).status===status).map(p=>`<article class="work-card"><div class="work-card-top"><span class="tag-inline">${esc(p.chain)}</span><span class="priority priority-${rec(p).priority}">${{low:'Rendah',normal:'Normal',high:'Tinggi'}[rec(p).priority]}</span></div><button class="work-title" data-open="${esc(p.id)}"><span>${p.symbol}</span>${esc(p.name)}</button><span class="campaign-stage">${esc(CLAIM_STAGES[rec(p).dossier.stage])}</span><div class="work-progress"><span>Checklist</span><b>${done(p)}/${p.tasks.length}</b></div><div class="progress"><span style="width:${done(p)/p.tasks.length*100}%"></span></div><p class="note-preview">${esc(rec(p).notes||'Tambahkan catatan dan langkah riset berikutnya.')}</p><div class="work-footer"><span>${icon('calendar')}${rec(p).due||'Atur tenggat'}</span><button class="text-btn" data-open="${esc(p.id)}">Kelola ${icon('arrow')}</button></div></article>`).join('')||`<div class="lane-empty">${icon(status==='completed'?'check':'layers')}<p>Belum ada exhibit</p></div>`}</section>`).join('')}</div>`}`}
function calendar(){const y=month.getFullYear(),m=month.getMonth(),start=(new Date(y,m,1).getDay()+6)%7,days=new Date(y,m+1,0).getDate(),due=all().filter(p=>state.saved.includes(p.id)&&rec(p).due&&rec(p).status!=='archived');return intro('Kalender riset.','Tanggal di sini adalah target pribadi yang Anda tetapkan, bukan tenggat resmi kampanye.',`<button class="secondary" id="export-calendar">Ekspor kalender ↓</button>`)+`<section class="panel"><div class="section-title"><button class="secondary" data-month="-1" aria-label="Bulan sebelumnya">←</button><h2>${month.toLocaleDateString('id-ID',{month:'long',year:'numeric'})}</h2><button class="secondary" data-month="1" aria-label="Bulan berikutnya">→</button></div><div class="calendar-grid">${['Sen','Sel','Rab','Kam','Jum','Sab','Min'].map(d=>`<b class="weekday">${d}</b>`).join('')}${Array.from({length:start},()=>'<div class="day blank"></div>').join('')}${Array.from({length:days},(_,i)=>{const date=`${y}-${String(m+1).padStart(2,'0')}-${String(i+1).padStart(2,'0')}`;return `<div class="day ${date===today()?'today':''}"><span>${i+1}</span>${due.filter(p=>rec(p).due===date).map(p=>`<button data-open="${esc(p.id)}">${esc(p.name)}</button>`).join('')}</div>`}).join('')}</div></section><section class="panel"><h3>Semua exhibit terjadwal</h3>${due.length?due.sort((a,b)=>rec(a).due.localeCompare(rec(b).due)).map(row).join(''):empty('Atur deadline di detail proyek untuk mulai menjadwalkan riset.')}</section>`}
function archiveLedger(){const list=all().filter(p=>rec(p).status==='archived'),recorded=all().filter(p=>rec(p).cost||rec(p).reward),cost=recorded.reduce((n,p)=>n+rec(p).cost,0),reward=recorded.reduce((n,p)=>n+rec(p).reward,0);return '<div class="section-title"><h2>Pencatatan hasil pribadi</h2></div>'+`<div class="stats">${[[list.length,'Exhibit diarsipkan'],[money(cost),'Biaya tercatat'],[money(reward),'Hasil tercatat'],[money(reward-cost),'Selisih tercatat']].map(([n,l])=>`<div class="stat"><div><b>${n}</b><small>${l}</small></div></div>`).join('')}</div><section class="panel"><h3>Riset diarsipkan</h3>${list.length?list.map(row).join(''):empty('Arsip masih kosong. Arsipkan proyek melalui pengaturan status di detail.')}</section><section class="panel"><h3>Ledger pribadi · USD</h3><p>Catatan manual pribadi, bukan saldo wallet atau bukti transaksi.</p>${recorded.length?`<div class="table-wrap"><table><thead><tr><th>Project</th><th>Cost</th><th>Reward</th><th>Net</th></tr></thead><tbody>${recorded.map(p=>`<tr><td><button class="text-btn" data-open="${esc(p.id)}">${esc(p.name)}</button></td><td>${money(rec(p).cost)}</td><td>${money(rec(p).reward)}</td><td>${money(rec(p).reward-rec(p).cost)}</td></tr>`).join('')}</tbody></table></div>`:empty('Belum ada biaya atau hasil dicatat.')}</section>`}
function profile(){const tab=['workspace','calendar','archive'].includes(page)?'portfolio':page==='referral'?'invite':profileTab;const xp=xpTotal(state.progress),level=levelInfo(xp);return `<section class="profile-cover"><div class="profile-cover-pattern" aria-hidden="true"></div><div class="profile-identity"><div class="profile-monogram">${esc((state.name||'M').slice(0,1).toUpperCase())}</div><div><span class="eyeline">MUSEUM EXPLORER / PERSONAL PASS</span><h1>${esc(state.name)}</h1><p>Ruang pribadi untuk koleksi, catatan, dan perjalanan riset Anda.</p></div><span class="profile-mode">${icon('shield')} Lv. ${level.level} · ${level.title}</span></div><div class="profile-metrics"><span><b>${xp}</b> XP lokal</span><span><b>${streak(state.progress)}</b> Hari streak</span><span><b>${state.saved.length}</b> Exhibit diikuti</span><span><b>${BADGES.filter(b=>badgeEarned(b,state)).length}</b> Badge</span></div></section><div class="section-tabs profile-tabs" role="group" aria-label="Bagian profil">${[['overview','Ringkasan'],['portfolio','Portofolio'],['badges','Badge & XP'],['invite','Ajak teman'],['data','Data & integrasi']].map(([key,label])=>`<button data-profile-tab="${key}" class="${tab===key?'active':''}" aria-pressed="${tab===key}">${label}</button>`).join('')}</div>${tab==='portfolio'?profilePortfolio():tab==='badges'?badgePage():tab==='invite'?inviteSection():tab==='data'?profileData():`<div class="profile-columns"><section class="panel"><div class="section-title"><div><span class="eyeline">YOUR IDENTITY</span><h2>Identitas penjelajah</h2></div>${icon('user')}</div><form id="profile-form"><label>Nama tampilan<input name="name" value="${esc(state.name)}" maxlength="60" required></label><p class="connection">Nama ini digunakan di profil browser Anda. Bukan identitas Telegram terverifikasi.</p><button class="primary">Simpan perubahan</button></form><div class="profile-shortcut"><span>${icon('share')}<b>Ajak teman menjelajahi museum</b></span><button class="text-btn" data-profile-tab="invite">Buka ${icon('arrow')}</button></div></section><section class="panel"><span class="eyeline">RESEARCH MILESTONES</span><h2>Jejak penjelajah</h2><div class="level-strip"><b>Level ${level.level}</b><span>${xp} / ${level.next} XP</span><div class="progress"><span style="width:${level.percent}%"></span></div></div><div class="badge-grid">${[['bookmark','Kolektor',state.saved.length>0,'Simpan satu exhibit'],['check','Langkah pertama',total()>0,'Selesaikan satu tugas'],['layers','Peneliti',total()>=12,'Selesaikan 12 tugas']].map(([ico,name,earned,desc])=>`<div class="badge ${earned?'earned':''}"><strong>${icon(ico)}</strong><b>${name}</b><small>${earned?'Tercapai':desc}</small></div>`).join('')}</div><p class="connection">Pencapaian lokal untuk menandai progres pribadi. Tidak memiliki nilai finansial.</p></section></div><section class="panel"><div class="section-title"><div><span class="eyeline">YOUR ACTIVITY</span><h2>Riwayat perjalanan</h2></div><button class="text-btn" data-profile-tab="data">Kelola data ${icon('arrow')}</button></div>${activity()}</section>`}`}
function render(){const active=primaryRoute(page);for(const id of ['desktop-nav','mobile-nav'])$('#'+id).innerHTML=nav.map(([key,ico,label])=>`<button data-nav="${key}" class="${active===key?'active':''}" ${active===key?'aria-current="page"':''}>${icon(ico)}<span>${label}</span>${id==='desktop-nav'&&active===key?'<span class="nav-dot"></span>':''}</button>`).join('');$('#page-label').textContent=nav.find(n=>n[0]===active)[2];$('#profile-top').textContent=(state.name||'M').slice(0,1).toUpperCase();$('#app').innerHTML=({home:dashboard,explore:discover,workspace:profile,calendar:profile,archive:profile,voices:voicesPage,profile,referral:profile,missions}[page])();refreshRadarButton();const selectedTab=$('.section-tabs button.active');if(selectedTab){const strip=selectedTab.parentElement;strip.scrollLeft=Math.max(0,selectedTab.offsetLeft-strip.offsetLeft+selectedTab.offsetWidth-strip.clientWidth+16)}if(page==='explore'){updateGrid();$('#search').value=query;$('#chain').value=chain;$('#mode').value=mode;$('#sort').value=sort}}
function taskList(p){return p.tasks.map((t,i)=>{const key=p.id+':'+i,status=state.done[key]?'done':state.taskStates[key]||'pending';return `<div class="task-state-row task-state-${status}"><button class="task ${status==='done'?'done':''}" data-task="${esc(key)}" aria-pressed="${status==='done'}"><span class="check">${status==='done'?'✓':i+1}</span><span>${esc(t)}</span></button><label class="task-state-label"><span>Status tugas ${i+1}</span><select data-task-state="${esc(key)}" aria-label="Status tugas ${i+1}">${Object.entries(TASK_STATUS).map(([key,label])=>`<option value="${key}" ${status===key?'selected':''}>${label}</option>`).join('')}</select></label></div>`}).join('')}
function showDetail(id){const p=project(id);if(!p)return;if(openId!==id){detailTab='overview';detailDraft=null}openId=id;const stored=rec(p),r=detailDraft?{...stored,...detailDraft,dossier:cleanDossier(detailDraft)}:stored;const detailBody=detailTab==='overview'?`<p class="detail-description">${esc(p.desc||'Lengkapi konteks proyek melalui catatan riset pribadi Anda.')}</p><div class="detail-facts"><div><small>Ekosistem</small><b>${esc(p.chain)}</b></div><div><small>Kategori</small><b>${esc(p.category)}</b></div><div><small>Status</small><b>${esc(CLAIM_STAGES[stored.dossier.stage])}</b></div></div><div class="detail-source"><span>${icon('globe')}<b>Sumber proyek</b><small>${p.website?esc(new URL(p.website).hostname):'Belum ada sumber'}</small></span>${p.website?`<button class="secondary" data-source="${esc(p.id)}">Periksa sumber ${icon('arrow')}</button>`:'<span class="source-badge">Contoh fiktif</span>'}</div>${campaignOverview(p)}${dossierView(p)}<div class="collection-disclosure">${icon('info')}<p>${p.custom?'Sumber dan bukti ditambahkan sendiri, belum diverifikasi oleh Museum.':'Exhibit demonstrasi fiktif; bukan kampanye airdrop nyata.'} Tidak ada jaminan eligibility atau reward.</p></div>`:detailTab==='reviews'?reviewForm(p):detailTab==='lab'?hunterExhibit(p):`<div class="task-summary"><div><h3>Checklist partisipasi</h3><p>Progres dicatat sendiri, bukan verifikasi on-chain.</p></div><b>${done(p)}<span>/${p.tasks.length}</span></b></div><div class="progress"><span style="width:${done(p)/p.tasks.length*100}%"></span></div>${taskList(p)}<form id="record-form" data-id="${esc(id)}"><h3>Pengaturan riset</h3><div class="form-grid"><label>Status<select name="status">${Object.entries(labels).map(([k,v])=>`<option value="${k}" ${r.status===k?'selected':''}>${v}</option>`).join('')}</select></label><label>Prioritas<select name="priority">${[['low','Rendah'],['normal','Normal'],['high','Tinggi']].map(([v,label])=>`<option value="${v}" ${r.priority===v?'selected':''}>${label}</option>`).join('')}</select></label><label>Tenggat pribadi<input type="date" name="due" value="${esc(r.due)}"></label><label>Biaya · USD<input type="number" name="cost" min="0" max="1000000000" step="0.01" value="${esc(r.cost)}"></label><label>Reward aktual · USD<input type="number" name="reward" min="0" max="1000000000" step="0.01" value="${esc(r.reward)}"></label></div>${dossierForm({...p,draftDossier:r.dossier})}<label>Catatan riset<textarea name="notes" maxlength="5000" rows="5" placeholder="Sumber yang ditinjau, temuan, dan langkah berikutnya…">${esc(r.notes)}</textarea></label><button class="primary">Simpan riset ${icon('check')}</button><p class="connection">Status, biaya, dan hasil adalah catatan pribadi Anda.</p></form>`;$('#detail-content').innerHTML=`<div class="exhibit-detail-head"><button class="close" id="close" aria-label="Tutup detail">${icon('close')}</button><span class="detail-symbol">${p.symbol}</span><div><span class="eyeline">EXHIBIT ${String(all().indexOf(p)+1).padStart(3,'0')} / ${p.custom?'PERSONAL':'DEMO'}</span><h2>${esc(p.name)}</h2><span class="detail-stage">${esc(p.chain)} <span>·</span> ${esc(p.category)}</span></div></div><div class="detail-toolbar"><button class="${state.saved.includes(id)?'secondary':'primary'}" data-save="${esc(id)}">${icon('bookmark')}${state.saved.includes(id)?'Dalam portofolio':'Simpan ke portofolio'}</button><span>${done(p)}/${p.tasks.length} tugas selesai</span></div><div class="section-tabs detail-tabs" role="group" aria-label="Bagian exhibit">${[['overview','Ringkasan & bukti'],['tasks','Tugas & catatan'],['reviews','Ulasan pribadi'],['lab','Hunter tools']].map(([key,label])=>`<button data-detail-tab="${key}" class="${detailTab===key?'active':''}" aria-pressed="${detailTab===key}">${label}</button>`).join('')}</div><div class="detail-body">${detailBody}</div>`;if(!$('#detail').open)$('#detail').showModal()}
function addProject(){if(!$('#project-editor'))document.body.insertAdjacentHTML('beforeend','<dialog id="project-editor"></dialog>');$('#project-editor').innerHTML=`<div class="detail-body"><div class="section-title"><h2>Add a project</h2><button class="secondary" id="close-editor">×</button></div><p>Tambahkan proyek riset Anda. Sumber tidak dianggap terverifikasi otomatis.</p><form id="new-project"><label>Project name<input name="name" maxlength="80" required></label><label>Official source URL<input name="website" type="url" placeholder="https://…" required></label><div class="form-grid"><label>Jenis peluang<select name="kind"><option value="airdrop">Airdrop research</option><option value="bounty">Bounty research</option><option value="testnet">Testnet research</option><option value="community">Community contribution</option></select></label><label>Category<select name="category">${['Testnet','DeFi','GameFi','Layer 2','RWA','Gaming','AI','Infra','NFT'].map(c=>`<option>${c}</option>`).join('')}</select></label><label>Chain<input name="chain" maxlength="40" required></label></div><label>Description<textarea name="desc" maxlength="500" rows="2"></textarea></label><label>Research tasks · one per line<textarea name="tasks" maxlength="6000" rows="5" placeholder="Review official documentation\nCheck campaign rules" required></textarea></label><p class="connection">Maksimal 30 tugas. Jangan masukkan seed phrase, private key, atau token.</p><button class="primary">Create & track project</button></form></div>`;$('#project-editor').showModal()}
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;const d=el.dataset;if(d.campaign){openCampaign(d.campaign);return}if(d.campaignCalendar){const p=project(d.campaignCalendar),c=state.campaigns[p.id];if(!c.deadline&&!c.snapshot)return toast('Belum ada tanggal kampanye.');download(campaignCalendar(p,c),'museum-campaign-'+p.id+'.ics','text/calendar');return}if(d.radarRead){state.radarRead=[...new Set([...state.radarRead,d.radarRead])].slice(-300);persist();render();return}if(el.id==='radar-read-all'){state.radarRead=[...new Set([...state.radarRead,...radarEvents(all(),state).map(e=>e.id)])].slice(-300);persist();render();return}if(d.huntOpen){showDetail(d.huntOpen);detailTab='lab';showDetail(d.huntOpen);return}if(d.proof){openProof(d.proof);return}if(d.brief){openBrief(d.brief);return}if(d.pack){const p=project(d.pack);download(researchPack(p,state),'museum-research-'+p.id+'.md','text/markdown');return}if(el.id==='close-hunter'){el.closest('dialog').close();return}if(d.missionTab){missionTab=d.missionTab;if(page!=='missions'){page='missions';location.hash='missions'}render();return}if(d.claim){try{state.progress=claimQuest(state,d.claim);persist('Claimed local XP: '+d.claim);toast('XP eksplorasi lokal berhasil diklaim.');render()}catch(err){toast(err.message)}return}if(d.blueprint){applyBlueprint(d.blueprint);return}if(el.id==='open-quiz'){openQuiz();return}if(el.id==='close-quiz'){$('#learning-dialog').close();return}if(el.id==='load-rewards'){loadRewards();return}if(el.id==='bind-invite'){bindInvite();return}if(el.id==='verify-quiz'){verifyQuiz();return}if(d.profileTab){profileTab=d.profileTab;page='profile';location.hash='profile';render();return}if(d.detailTab){const form=$('#record-form');if(form)detailDraft=Object.fromEntries(new FormData(form));detailTab=d.detailTab;showDetail(openId);return}if(d.view){portfolioView=d.view;render();return}if(d.nav)return navigate(d.nav);if(d.category){category=d.category;return updateGrid()}if(d.open)return showDetail(d.open);if(d.source)return sourceGate(d.source);if(d.save){const p=project(d.save);if(!p)return;const saved=state.saved.includes(p.id);state.saved=saved?state.saved.filter(id=>id!==p.id):[...state.saved,p.id];if(!saved&&rec(p).status==='archived')rec(p).status='watching';persist(`${saved?'Untracked':'Tracked'} ${p.name}`);render();if($('#detail').open)showDetail(p.id);return}if(d.task){const id=openId,p=project(id);if(!p)return;const form=$('#record-form');if(form){const draft=Object.fromEntries(new FormData(form));state.records[id]={...state.records[id],...draft,dossier:cleanDossier(draft)};state=normalize(state,demos);detailDraft=null}state.done[d.task]=!state.done[d.task];if(!state.done[d.task])delete state.taskStates[d.task];else state.taskStates[d.task]='done';if(!state.saved.includes(id))state.saved.push(id);persist(`Updated checklist: ${p.name}`);render();showDetail(id);return}if(d.month){month=new Date(month.getFullYear(),month.getMonth()+Number(d.month),1);render();return}if(el.id==='add-project')addProject();if(el.id==='close')$('#detail').close();if(el.id==='close-editor')$('#project-editor').close();if(el.id==='copy-invite')return copyInvite();if(el.id==='share-invite')return shareInvite();if(el.id==='export')download(JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2),'airdrop-museum-backup.json','application/json');if(el.id==='export-calendar'){const events=all().filter(p=>state.saved.includes(p.id)&&rec(p).due&&rec(p).status!=='archived').map(p=>icsEvent(p,rec(p)));if(!events.length)return toast('Belum ada deadline untuk diekspor.');download(['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Airdrop Museum//Research Calendar//ID',...events,'END:VCALENDAR'].join('\r\n'),'airdrop-museum.ics','text/calendar')}});
document.addEventListener('click',e=>{if(e.target.id==='clear-local-data'&&confirm('Hapus seluruh proyek, catatan, ulasan, dan progres yang tersimpan di browser ini? File backup yang sudah diunduh tidak akan ikut terhapus.')){localStorage.removeItem('airdrop-museum-v1');state=normalize({},demos);render();toast('Semua data lokal telah dihapus.')}});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;updateGrid()}});
document.addEventListener('change',async e=>{if(['chain','mode','sort'].includes(e.target.id)){if(e.target.id==='chain')chain=e.target.value;if(e.target.id==='mode')mode=e.target.value;if(e.target.id==='sort')sort=e.target.value;updateGrid()}if(e.target.id==='import'){try{const file=e.target.files?.[0];if(!file)return;if(file.size>1000000)throw Error('Backup melebihi 1 MB.');state=mergeBackup(state,backup(await file.text(),demos),demos);persist('Imported backup');render();toast('Backup berhasil digabungkan.')}catch(err){toast(err.message)}}});
document.addEventListener('submit',e=>{if(!['new-project','record-form','profile-form','review-form'].includes(e.target.id))return;e.preventDefault();const data=Object.fromEntries(new FormData(e.target));try{if(e.target.id==='new-project'){if(state.custom.length>=100)throw Error('Maksimal 100 proyek pribadi.');const p=cleanProject({...data,id:'custom-'+(globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2)),tasks:data.tasks.split('\n')});state.custom.push(p);state.saved.push(p.id);state=normalize(state,demos);persist(`Created ${p.name}`);$('#project-editor').close();navigate('workspace');showDetail(p.id)}else if(e.target.id==='record-form'){const id=e.target.dataset.id;state.records[id]={...state.records[id],...data,dossier:cleanDossier(data)};detailDraft=null;state=normalize(state,demos);if(!state.saved.includes(id))state.saved.push(id);persist(`Saved research: ${project(id).name}`);render();showDetail(id);toast('Research saved.')}else if(e.target.id==='review-form'){const p=project(e.target.dataset.id);state.reviews.unshift(cleanReview({...data,projectId:p.id}));state.reviews=state.reviews.slice(0,100);persist(`Added local review: ${p.name}`);render();showDetail(p.id);toast('Ulasan tersimpan lokal, belum dipublikasikan.')}else{state.name=data.name.trim()||'Museum Explorer';persist('Updated local profile');render();toast('Profile saved.')}}catch(err){let feedback=e.target.querySelector('.form-error');if(!feedback){feedback=document.createElement('p');feedback.className='notice form-error';feedback.setAttribute('role','alert');e.target.append(feedback)}feedback.textContent=err.message;toast(err.message)}});
$('#profile-top').onclick=()=>navigate('profile');$('#detail').addEventListener('click',e=>{if(e.target===e.currentTarget)e.currentTarget.close()});window.addEventListener('hashchange',()=>{const id=location.hash.slice(1);if(resolveRoute(id)===id&&id!==page){page=id;render()}});
page=resolveRoute(location.hash.slice(1));if(page==='referral')profileTab='invite';render();
const tg=window.Telegram?.WebApp;if(tg?.initData){try{tg.ready();tg.expand();if(tg.isVersionAtLeast('6.1')){tg.setHeaderColor('#f5f6f7');tg.setBackgroundColor('#f5f6f7')}tg.BackButton.onClick(()=>{if($('#detail').open)$('#detail').close();else navigate('home')});tg.BackButton.show()}catch{}}

function dashboard(){const tracked=all().filter(p=>state.saved.includes(p.id)&&rec(p).status!=='archived'),active=tracked.filter(p=>rec(p).status==='active'),scheduled=tracked.filter(p=>rec(p).due&&!['completed','archived'].includes(rec(p).status)).sort((a,b)=>rec(a).due.localeCompare(rec(b).due)),complete=tracked.reduce((n,p)=>n+done(p),0),tasks=tracked.reduce((n,p)=>n+p.tasks.length,0);return intro(`Ruang eksplorasi Anda.`,`Selamat datang, ${esc(state.name)}. Temukan konteks, simpan bukti, dan susun langkah berikutnya.`,`<button class="secondary" data-nav="workspace">${icon('layers')} Portofolio saya</button>`)+`<section class="welcome-hero"><div class="hero-content"><span class="hero-kicker"><span></span> THE OPEN COLLECTION / 2026</span><h2>Setiap peluang punya cerita.<br><em>Mulai dari buktinya.</em></h2><p>Museum digital untuk menelaah airdrop—dari sumber dan sinyal risiko, sampai jejak partisipasi Anda.</p><div class="hero-actions"><button class="primary" data-nav="explore">Jelajahi koleksi ${icon('arrow')}</button><button class="hero-link" data-nav="voices">Bagaimana penilaian bekerja?</button></div></div><div class="hero-installation" aria-hidden="true"><div class="installation-ring"></div><div class="installation-plaque"><img src="brand.jpg" alt=""><span>AIRDROP<br>MUSEUM</span><small>OBSERVE / DOCUMENT / DECIDE</small></div><div class="installation-pedestal"></div><span class="installation-label">EXHIBITION NO. 001</span></div></section>`+xpOverview()+stats()+radarDigest()+hunterDigest()+`<div class="dashboard-columns"><section class="panel continue-panel"><div class="section-title"><div><span class="eyeline">PERSONAL RESEARCH</span><h2>Lanjutkan perjalanan</h2></div><button class="text-btn" data-nav="workspace">Lihat semua ${icon('arrow')}</button></div>${active.length?active.slice(0,3).map(row).join(''):`<div class="guided-empty">${icon('layers')}<h3>Koleksi Anda menunggu cerita pertama.</h3><p>Pilih exhibit, tambahkan ke portofolio, lalu mulai checklist riset Anda.</p><button class="secondary" data-nav="explore">Pilih exhibit pertama ${icon('arrow')}</button></div>`}<div class="collection-progress"><div><b>Progres koleksi</b><span>${complete} dari ${tasks} tugas</span></div><div class="progress"><span style="width:${tasks?complete/tasks*100:0}%"></span></div></div></section><section class="panel deadline-panel"><div class="section-title"><div><span class="eyeline">YOUR SCHEDULE</span><h2>Tenggat berikutnya</h2></div><button class="icon-button" data-nav="calendar" aria-label="Buka kalender">${icon('calendar')}</button></div>${scheduled.length?scheduled.slice(0,3).map(row).join(''):`<div class="schedule-empty"><div class="calendar-mini"><span>${new Date().toLocaleDateString('id-ID',{month:'short'}).toUpperCase()}</span><b>${new Date().getDate()}</b></div><h3>Rencanakan langkah Anda.</h3><p>Tambahkan tenggat pribadi di detail exhibit. Semua jadwal akan terhubung ke portofolio.</p></div>`}<button class="text-btn" data-nav="calendar">Lihat kalender ${icon('arrow')}</button></section></div><div class="section-title gallery-title"><div><span class="eyeline">THE MUSEUM DIRECTORY</span><h2>Di dalam galeri</h2></div><button class="text-btn" data-nav="explore">Semua exhibit ${icon('arrow')}</button></div><div class="grid">${all().slice(0,3).map(card).join('')}</div>${dashboardMissions()}<div class="collection-disclosure">${icon('info')}<p>Exhibit bawaan adalah contoh fiktif untuk eksplorasi fitur. Proyek pribadi dan progres tetap milik Anda; tidak ada jaminan reward atau eligibility.</p><button class="text-btn" data-nav="profile">Kelola data ${icon('arrow')}</button></div>`}
function dossierView(p){const d=rec(p).dossier;return `<section class="dossier"><div class="section-title"><h3>Dossier transparansi</h3><span class="trust-unrated">◌ Belum dinilai</span></div><p>Skor publik 0–2800 memerlukan bukti dan metode terverifikasi. Data kosong tidak dianggap aman atau berisiko.</p><dl>${[['Tahap kampanye',CLAIM_STAGES[d.stage]],['Audit kontrak',d.audit],['Aktivitas tim publik',d.team],['Treasury / likuiditas',d.treasury],['Bukti on-chain / snapshot',d.chainEvidence],['Sinyal risiko',d.risks],['Tinjauan pribadi terakhir',d.checkedAt],['Hasil distribusi',d.outcome]].map(([key,value])=>`<div><dt>${key}</dt><dd>${esc(value||'Belum ada bukti tercatat')}</dd></div>`).join('')}</dl><small>Catatan diisi pemilik, tersimpan lokal di browser, dan belum diverifikasi.</small></section>`}
function dossierForm(p){const d=p.draftDossier||rec(p).dossier;return `<details class="evidence-editor"><summary>Ubah dossier transparansi</summary><label>Tahap kampanye<select name="stage">${Object.entries(CLAIM_STAGES).map(([k,v])=>`<option value="${k}" ${d.stage===k?'selected':''}>${v}</option>`).join('')}</select></label>${[['audit','Audit · sumber / temuan',500],['team','Aktivitas tim · sumber / temuan',500],['treasury','Treasury / likuiditas · sumber / temuan',500],['chainEvidence','On-chain / snapshot · bukti',500],['risks','Sinyal risiko · pengamatan',1000],['outcome','Hasil distribusi · bukti',1000]].map(([key,title,max])=>`<label>${title}<textarea name="${key}" maxlength="${max}" rows="2">${esc(d[key])}</textarea></label>`).join('')}<label>Tanggal tinjauan pribadi<input type="date" name="checkedAt" value="${d.checkedAt}"></label></details>`}
function reviewForm(p){return `<section class="visitor-notes"><h3>Catatan pengunjung · tersimpan lokal</h3><p>Ulasan tersimpan di browser ini. Belum ada publikasi, voting komunitas, atau reputasi on-chain.</p>${state.reviews.filter(r=>r.projectId===p.id).slice(0,5).map(r=>`<blockquote><b>${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</b><p>${esc(r.text)}</p><small>Local note · ${esc(new Date(r.at).toLocaleDateString('id-ID'))}</small></blockquote>`).join('')}<form id="review-form" data-id="${esc(p.id)}"><label>Penilaian pribadi<select name="rating">${[5,4,3,2,1].map(n=>`<option>${n}</option>`).join('')}</select></label><label>Pengamatan Anda<textarea name="text" maxlength="2000" rows="3" required></textarea></label><button class="secondary">Simpan ulasan lokal</button></form></section>`}
function voices(){return intro('Panduan transparansi.','Penilaian pengunjung memperkaya exhibit, tanpa menyembunyikan informasi dari galeri.')+`<section class="panel methodology"><span class="eyeline">TRUST SCORE / WHITEPAPER FRAMEWORK</span><h2>A score needs a visible foundation.</h2><p>Whitepaper mengusulkan audit, usia proyek, treasury, aktivitas tim, bukti on-chain, serta masukan komunitas. Implementasi saat ini menyimpan dossier pribadi; tidak menghasilkan skor kredibilitas publik.</p><div class="score-scale">${TRUST_BANDS.map(([range,label])=>`<div><b>${range}</b><small>${label}</small></div>`).join('')}</div><div class="notice">Rentang di atas adalah rancangan whitepaper, bukan rating exhibit yang sudah diverifikasi. Skor tidak menjamin keamanan atau reward.</div></section><div class="split"><section class="panel"><h3>Vouch & slash</h3><p>Direncanakan dalam whitepaper. Belum ada staking token, pemotongan reputasi, kontrak, atau transaksi keuangan yang aktif.</p><span class="tag-inline">Roadmap · not active</span></section><section class="panel"><h3>Public visitor voice</h3><p>Memerlukan identitas terverifikasi, penyimpanan bersama, kebijakan sengketa, dan perlindungan manipulasi sebelum dapat dibuka.</p><span class="tag-inline">Roadmap · not active</span></section></div><section class="panel"><h3>Your local review notebook</h3>${state.reviews.length?state.reviews.map(r=>`<article class="review-item"><button class="text-btn" data-open="${esc(r.projectId)}">${esc(project(r.projectId)?.name||'Exhibit')} ↗</button><b>${'★'.repeat(r.rating)}</b><p>${esc(r.text)}</p><small>Private browser note · ${esc(new Date(r.at).toLocaleDateString('id-ID'))}</small></article>`).join(''):empty('Buka detail exhibit untuk menulis ulasan pribadi pertama Anda.')}</section>`}
function sourceGate(id){const p=project(id)||RESOURCES.find(r=>r.id===id);if(!p?.website)return;const u=new URL(p.website);if(!$('#source-gate'))document.body.insertAdjacentHTML('beforeend','<dialog id="source-gate"></dialog>');const gate=$('#source-gate');gate.innerHTML=`<div class="detail-body"><span class="eyeline">BEFORE YOU LEAVE THE MUSEUM</span><h2>Inspect the destination.</h2><p>Anda akan membuka sumber eksternal di tab baru.</p><div class="source-host">${esc(u.hostname)}</div><p class="source-url">${esc(u.href)}</p><ul>${sourceSignals(p.website).map(s=>`<li>${esc(s)}</li>`).join('')}</ul><div class="notice">Jangan berikan seed phrase atau private key. Periksa domain, izin wallet, dan rincian transaksi secara mandiri.</div><div class="data-actions"><button class="secondary" id="cancel-source">Return to exhibit</button>${u.username||u.password?'':`<a class="primary" href="${esc(u.href)}" target="_blank" rel="noopener noreferrer">Open external source ↗</a>`}</div></div>`;gate.querySelector('#cancel-source').onclick=()=>gate.close();gate.showModal()}

function copyInvite(){const field=$('#invite-url');if(!field)return;const fallback=()=>{field.focus();field.select();const copied=document.execCommand('copy');toast(copied?'Tautan ajakan disalin.':'Pilih tautan lalu salin secara manual.')};if(navigator.clipboard?.writeText)navigator.clipboard.writeText(field.value).then(()=>toast('Tautan ajakan disalin.')).catch(fallback);else fallback()}
function shareInvite(){const data=currentInvite();if(navigator.share)navigator.share(data).catch(err=>{if(err.name!=='AbortError')toast('Berbagi tidak tersedia. Anda dapat menyalin tautan.')});else copyInvite()}
function archive(){const history=all().filter(p=>['snapshot','closed','failed','risk_reported'].includes(rec(p).dossier.stage));return intro('Arsip & hasil riset.','Snapshot, distribusi, kegagalan, dan risiko yang dicatat—tetap menjadi bahan pembelajaran.')+`<section class="panel"><span class="eyeline">EXHIBIT HISTORY / PERSONAL RECORDS</span><h3>Document the outcome, not just the reward.</h3>${history.length?history.map(p=>`<article class="history-exhibit"><div class="section-title"><button class="text-btn" data-open="${esc(p.id)}">${esc(p.name)} ↗</button><span class="tag-inline">${esc(CLAIM_STAGES[rec(p).dossier.stage])}</span></div><p>${esc(rec(p).dossier.outcome||'Belum ada bukti hasil distribusi yang dicatat.')}</p><small>Personal report · ${esc(rec(p).dossier.checkedAt||'Review date unknown')}</small></article>`).join(''):empty('Catat tahap snapshot, distribusi selesai, gagal, atau risiko dilaporkan di dossier exhibit agar masuk riwayat ini.')}</section>`+archiveLedger()}

function syncPanel(){const active=serverInfo?.sync&&!!window.Telegram?.WebApp?.initData;return `<section class="panel"><span class="eyeline">YOUR DATA / YOUR CONTROL</span><h3>Sinkronisasi pribadi</h3><div class="status-row"><b>Penyimpanan server</b><span>${serverInfo?.database==='ready'?'Tersedia':serverInfo?'Belum tersedia':'Memeriksa…'}</span></div><p>Ambil & gabungkan akan membaca data akun ke browser. Kirim ke cloud akan menyimpan nama, proyek, catatan, ulasan pribadi, jadwal, dan ledger ke akun Telegram Anda. Data tidak menjadi ulasan publik. Sinkronisasi berjalan hanya saat Anda menekan tombol.</p><p class="connection">${active?'Autentikasi Telegram tersedia. Ambil data terlebih dahulu untuk memperoleh revisi terbaru.':'Sinkronisasi belum aktif. Token bot proyek perlu dikonfigurasi; aplikasi lokal tetap dapat digunakan.'}</p><div class="data-actions"><button class="secondary" id="cloud-read" ${!active||syncBusy?'disabled':''}>Ambil & gabungkan</button><button class="primary" id="cloud-write" ${!active||syncBusy||cloudRevision===null?'disabled':''}>Kirim ke cloud</button></div><p class="connection">${cloudRevision===null?'Belum membaca revisi server.':'Revisi server terakhir: '+cloudRevision} · Konflik perubahan akan ditolak agar data perangkat lain tidak tertimpa.</p></section>`}
async function cloudAction(action){if(syncBusy)return;const initData=window.Telegram?.WebApp?.initData;if(!serverInfo?.sync||!initData)return toast('Sinkronisasi belum tersedia.');if(action==='write'&&cloudRevision===null)return toast('Ambil data server terlebih dahulu.');syncBusy=true;render();try{const headers={'X-Telegram-Init-Data':initData};const options={headers};if(action==='write'){headers['Content-Type']='application/json';headers['If-Match']=String(cloudRevision);options.method='PUT';options.body=JSON.stringify(state)}const response=await fetch('/api/me/state',options);const data=await response.json();if(!response.ok){if(response.status===409){cloudRevision=null;throw Error('Data server berubah. Ambil & gabungkan kembali sebelum mengirim.')}if(response.status===401)throw Error('Sesi Telegram kedaluwarsa. Buka ulang Mini App.');throw Error('Sinkronisasi gagal: '+(data.error||response.status))}if(action==='read'&&data.state){state=mergeBackup(state,backup(JSON.stringify(data.state),demos),demos);persist('Merged private cloud backup')}cloudRevision=data.revision;toast(action==='read'?'Data server dibaca dan digabungkan.':'Data tersimpan ke akun Anda.')}catch(err){toast(err.message)}finally{syncBusy=false;render()}}
document.addEventListener('click',e=>{if(e.target.closest('#cloud-read'))cloudAction('read');if(e.target.closest('#cloud-write'))cloudAction('write')});
fetch('/api/capabilities').then(async r=>{if(!r.ok)throw Error();serverInfo=await r.json();if(primaryRoute(page)==='profile'&&!document.activeElement?.closest('form'))render()}).catch(()=>{serverInfo={database:'unavailable',sync:false};if(primaryRoute(page)==='profile'&&!document.activeElement?.closest('form'))render()});
function icon(name){const paths={home:'M3 10.5 12 3l9 7.5V21h-6v-7H9v7H3Z',compass:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Zm4 5-2.5 5.5L8 16l2.5-5.5Z',layers:'m12 3 10 5-10 5L2 8Zm-9 9 9 4.5 9-4.5M3 16l9 4.5 9-4.5',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM4 21v-2a8 8 0 0 1 16 0v2',arrow:'M5 12h14m-5-5 5 5-5 5',plus:'M12 5v14M5 12h14',bookmark:'M6 3h12v18l-6-4-6 4Z',calendar:'M4 5h16v16H4ZM8 2v6m8-6v6M4 10h16',check:'m5 12 4 4L19 6',activity:'M2 12h5l3-8 4 16 3-8h5',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM3 12h18M12 3c5 5 5 13 0 18-5-5-5-13 0-18Z',info:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM12 11v6m0-10v1',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Zm-4 9 3 3 5-6',search:'M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0Zm-2 5 6 6',share:'M16 5 8 10m0 4 8 5M8 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0Zm14-8a3 3 0 1 1-6 0 3 3 0 0 1 6 0Zm0 16a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z',board:'M3 4h5v16H3Zm7 0h5v10h-5Zm7 0h5v13h-5Z',list:'M8 6h13M8 12h13M8 18h13M3 6h1m-1 6h1m-1 6h1',close:'m6 6 12 12M6 18 18 6',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',lock:'M6 10h12v11H6ZM8 10V6a4 4 0 0 1 8 0v4',mail:'M3 5h18v14H3Zm0 0 9 8 9-8'};return `<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.layers}"/></svg>`}
function portfolioTabs(active){return `<div class="section-tabs" role="group" aria-label="Bagian portofolio">${[['workspace','layers','Exhibit diikuti'],['calendar','calendar','Kalender'],['archive','activity','Arsip & hasil']].map(([key,ico,label])=>`<button data-nav="${key}" class="${active===key?'active':''}" aria-pressed="${active===key}">${icon(ico)}${label}</button>`).join('')}</div>`}
function galleryTabs(active){return `<div class="section-tabs" role="group" aria-label="Bagian jelajahi">${[['explore','compass','Direktori exhibit'],['voices','shield','Panduan transparansi']].map(([key,ico,label])=>`<button data-nav="${key}" class="${active===key?'active':''}" aria-pressed="${active===key}">${icon(ico)}${label}</button>`).join('')}</div>`}
function withoutIntro(markup){const t=document.createElement('template');t.innerHTML=markup;t.content.querySelector('.intro')?.remove();return t.innerHTML}
function calendarPage(){return intro('Kalender riset.','Jadwalkan langkah berikutnya dan pantau target pribadi Anda.',`<button class="secondary" id="export-calendar">${icon('download')} Ekspor kalender</button>`)+portfolioTabs('calendar')+withoutIntro(calendar())}
function archivePage(){return intro('Arsip & hasil riset.','Simpan jejak partisipasi dan catat hasil aktual tanpa estimasi reward.')+portfolioTabs('archive')+withoutIntro(archive())}
function voicesPage(){return intro('Panduan transparansi.','Pahami cara membaca bukti, risiko, dan penilaian di Museum.')+galleryTabs('voices')+withoutIntro(voices())}
function profileData(){return `<div class="profile-columns"><section class="panel"><div class="section-title"><div><span class="eyeline">BACKUP & RECOVERY</span><h2>Cadangan Anda</h2></div>${icon('download')}</div><p>Bawa proyek, catatan, jadwal, ulasan, dan ledger pribadi ke perangkat lain melalui file JSON.</p><div class="backup-actions"><button class="secondary" id="export">${icon('download')} Ekspor cadangan penuh</button><label class="secondary import-label">${icon('layers')} Impor & gabungkan<input id="import" type="file" accept="application/json,.json"></label></div><p class="connection">Impor mempertahankan pengaturan proyek yang sudah ada. File cadangan memuat data pribadi—simpan dengan aman.</p></section><section class="panel"><div class="section-title"><div><span class="eyeline">CONNECTED SERVICES</span><h2>Status layanan</h2></div>${icon('globe')}</div><div class="status-row"><span>Server Museum</span><b class="service-status ${serverInfo?.database==='ready'?'ready':''}">${serverInfo?.database==='ready'?'Tersedia':'Memeriksa / tidak tersedia'}</b></div><div class="status-row"><span>Sinkronisasi Telegram</span><b class="service-status">${serverInfo?.sync?'Siap dikonfigurasi di Telegram':'Belum aktif'}</b></div><div class="status-row"><span>Wallet & klaim</span><b class="service-status">Tidak terhubung</b></div><div class="status-row"><span>Ulasan publik</span><b class="service-status">Belum aktif</b></div></section></div>${syncPanel()}<section class="panel privacy-panel"><div><span class="eyeline">PRIVACY BY DEFAULT</span><h2>Data Anda, kendali Anda.</h2><p>Catatan tersimpan di browser ini dan tidak dikirim ke cloud tanpa tindakan sinkronisasi Anda. Orang lain yang memakai profil browser sama mungkin dapat mengaksesnya. Jangan masukkan seed phrase, private key, token, atau data sensitif.</p><details><summary>Detail penyimpanan & koneksi pihak ketiga</summary><p>Ekspor menghasilkan file JSON berisi data pribadi. Menghapus data lokal tidak menghapus file backup atau cadangan cloud yang sebelumnya dikirim. Halaman memuat Telegram Web App SDK dari telegram.org dan Google Fonts; penyedia dapat menerima metadata koneksi web standar seperti alamat IP dan user-agent.</p></details></div><div class="danger-zone"><h3>Hapus data lokal</h3><p>Semua proyek dan catatan di browser ini akan dihapus. Buat cadangan dahulu bila diperlukan.</p><button class="danger-button" id="clear-local-data">Hapus semua data lokal</button></div></section>`}
function profilePortfolio(){const active=page==='calendar'?'calendar':page==='archive'?'archive':'workspace';return withoutIntro(active==='calendar'?calendarPage():active==='archive'?archivePage():portfolioBody())}
function xpOverview(){const xp=xpTotal(state.progress),info=levelInfo(xp),claimed=state.progress.claims.length;return `<section class="xp-overview"><div class="xp-emblem">${icon('activity')}<b>${info.level}</b></div><div class="xp-progress"><span class="eyeline">EXPLORER PROGRESSION / LOCAL XP</span><div><h3>${info.title} <span>Level ${info.level}</span></h3><b>${xp}<small> XP</small></b></div><div class="progress"><span style="width:${info.percent}%"></span></div><p>${info.next-xp} XP menuju level ${info.level+1}</p></div><div class="xp-mini"><b>${streak(state.progress)}</b><span>hari streak</span></div><div class="xp-mini"><b>${BADGES.filter(b=>badgeEarned(b,state)).length}/${BADGES.length}</b><span>badge terbuka</span></div><button class="secondary" data-nav="missions">Misi XP ${icon('arrow')}</button></section>`}
function questCard(q){const count=q.count(state),claimed=state.progress.claims.includes(q.id),eligible=count>=q.target;return `<article class="quest-card ${claimed?'claimed':''}"><div class="quest-top"><span>${icon(q.icon)}</span><b>+${q.xp} XP</b></div><h3>${esc(q.title)}</h3><p>${esc(q.desc)}</p><div class="quest-progress"><span>${Math.min(count,q.target)}/${q.target}</span><span>${claimed?'Selesai':eligible?'Siap diklaim':'Dalam progres'}</span></div><div class="progress"><span style="width:${Math.min(100,count/q.target*100)}%"></span></div><div class="quest-bottom">${claimed?`<span>${icon('check')} XP telah diklaim</span>`:eligible?`<button class="primary" data-claim="${q.id}">Klaim XP ${icon('plus')}</button>`:`<button class="secondary" ${q.id==='safety-quiz'?'id="open-quiz"':['proof-trail','bounty-brief'].includes(q.id)?'data-mission-tab="lab"':`data-nav="${['first-save','first-project'].includes(q.id)?'explore':'workspace'}"`}>${q.id==='safety-quiz'?'Mulai pelajaran':'Kerjakan misi'} ${icon('arrow')}</button>`}<span class="source-badge">Lokal</span></div></article>`}
function dashboardMissions(){return `<div class="section-title gallery-title"><div><span class="eyeline">MAKE YOUR NEXT MOVE</span><h2>Misi untuk perjalanan Anda</h2></div><button class="text-btn" data-nav="missions">Semua misi ${icon('arrow')}</button></div><div class="quest-grid">${QUESTS.filter(q=>!state.progress.claims.includes(q.id)).slice(0,3).map(questCard).join('')||`<section class="panel"><h3>Misi penjelajah selesai.</h3><p>Lanjutkan riset dan aktivitas harian untuk menjaga streak Anda.</p></section>`}</div>`}
function missions(){return intro('Misi, bounty & pengetahuan.','Bangun kebiasaan riset Web3. XP adalah progres aplikasi, bukan token atau janji hadiah.',`<button class="secondary" data-profile-tab="badges">${icon('shield')} Koleksi badge</button>`)+`<div class="section-tabs" role="group" aria-label="Bagian misi">${[['quests','activity','Misi XP'],['bounties','compass','Bounty toolkit'],['learn','shield','Belajar Web3'],['lab','layers','Hunter Lab'],['radar','calendar','Radar']].map(([key,ico,label])=>`<button data-mission-tab="${key}" class="${missionTab===key?'active':''}" aria-pressed="${missionTab===key}">${icon(ico)}${label}</button>`).join('')}</div>`+(missionTab==='radar'?radarPage():missionTab==='lab'?hunterLab():missionTab==='bounties'?bountyToolkit():missionTab==='learn'?learningHub():`${xpOverview()}<section class="daily-mission"><div class="daily-icon">${icon('calendar')}</div><div><span class="eyeline">DAILY RESEARCH / +15 LOCAL XP</span><h3>Satu langkah riset hari ini.</h3><p>Selesaikan checklist, simpan riset, buat proyek, tulis ulasan, atau lulus pelajaran untuk mengaktifkan misi harian.</p></div><button class="${state.progress.days.includes(dayKey())?'primary':'secondary'}" data-claim="daily:${dayKey()}" ${!state.progress.days.includes(dayKey())||state.progress.claims.includes('daily:'+dayKey())?'disabled':''}>${state.progress.claims.includes('daily:'+dayKey())?'Sudah diklaim':state.progress.days.includes(dayKey())?'Klaim +15 XP':'Belum ada aktivitas'}</button></section><div class="section-title"><h2>Explorer missions</h2><small>${state.progress.claims.filter(id=>!id.startsWith('daily:')).length}/${QUESTS.length} selesai</small></div><div class="quest-grid">${QUESTS.map(questCard).join('')}</div><div class="collection-disclosure">${icon('info')}<p>XP dan badge eksplorasi bersifat lokal, dapat ikut backup, dan tidak digunakan sebagai trust score, saldo wallet, atau bukti eligibility.</p></div>`)}
function bountyToolkit(){return `<section class="bounty-intro"><div><span class="eyeline">WORK WITH CONTEXT</span><h2>Dari brief ke bukti kontribusi.</h2><p>Gunakan template untuk membangun rencana kerja bounty, testnet, atau kontribusi. Ini bukan daftar pekerjaan berbayar aktif; reward dan syarat mengikuti program sumber.</p><button class="primary" id="add-project">${icon('plus')} Tambah program pribadi</button></div><div class="bounty-map">${['Temukan brief resmi','Catat scope & aturan','Kerjakan dan dokumentasikan','Simpan bukti pengiriman'].map((t,i)=>`<div><b>${i+1}</b><span>${t}</span>${i===3?icon('check'):icon('arrow')}</div>`).join('')}</div></section><div class="section-title"><h2>Checklist siap disesuaikan</h2><small>Template riset · bukan kampanye aktif</small></div><div class="toolkit-grid">${BLUEPRINTS.map((b,i)=>`<article class="panel blueprint-card"><span class="blueprint-no">PLAYBOOK / 0${i+1}</span><h3>${b.title}</h3><p>${b.desc}</p><div><span>${b.tasks.length} langkah</span><button class="text-btn" data-blueprint="${b.id}">Gunakan template ${icon('arrow')}</button></div></article>`).join('')}</div><div class="section-title"><h2>Sumber eksternal resmi</h2><small>Periksa aturan langsung di sumber</small></div>${resourceCards()}`}
function resourceCards(){return `<div class="resource-grid">${RESOURCES.map(r=>`<button class="resource-card" data-source="${r.id}"><span class="resource-icon">${icon(r.icon)}</span><span class="resource-copy"><small>${r.type}</small><b>${r.name}</b><span>${r.desc}</span></span>${icon('arrow')}</button>`).join('')}</div>`}
function learningHub(){return `<section class="learning-feature"><span class="learning-icon">${icon('shield')}</span><div><span class="eyeline">START WITH SAFETY</span><h2>Wallet Safety 101</h2><p>Tiga pertanyaan tentang seed phrase, approval, dan risiko. Lulus untuk membuka badge Wallet Guardian dan misi +50 XP lokal.</p><button class="primary" id="open-quiz">${state.progress.quizPassed?'Ulangi pelajaran':'Mulai pelajaran'} ${icon('arrow')}</button></div><span class="learning-reward">+50<small>LOCAL XP</small></span></section><div class="section-title"><h2>Kamus penjelajah</h2><small>8 konsep penting</small></div><div class="glossary-grid">${GLOSSARY.map(([term,meaning])=>`<details><summary>${term}${icon('plus')}</summary><p>${meaning}</p></details>`).join('')}</div><div class="section-title gallery-title"><h2>Belajar langsung dari sumber</h2></div>${resourceCards()}`}
function openQuiz(){if(!$('#learning-dialog'))document.body.insertAdjacentHTML('beforeend','<dialog id="learning-dialog"></dialog>');$('#learning-dialog').innerHTML=`<div class="exhibit-detail-head"><button class="close" id="close-quiz" aria-label="Tutup pelajaran">${icon('close')}</button><span class="detail-symbol">${icon('shield')}</span><div><span class="eyeline">LEARN / WALLET SAFETY 101</span><h2>Mulai dari keamanan.</h2><span class="detail-stage">3 pertanyaan · badge Wallet Guardian</span></div></div><div class="detail-body"><form id="quiz-form">${QUIZ.map((q,i)=>`<fieldset class="quiz-question"><legend>${i+1}. ${q.question}</legend>${q.options.map((option,n)=>`<label><input type="radio" name="q${i}" value="${n}" required><span>${option}</span></label>`).join('')}</fieldset>`).join('')}<button class="primary">Periksa jawaban ${icon('check')}</button></form><div id="quiz-result" role="status"></div><div class="collection-disclosure">${icon('info')}<p>Materi ringkas berdasarkan panduan keamanan Ethereum. Ini pelajaran dasar, bukan audit keamanan atau nasihat investasi.</p></div></div>`;$('#learning-dialog').showModal()}
document.addEventListener('submit',e=>{if(e.target.id!=='quiz-form')return;e.preventDefault();const form=new FormData(e.target),answers=QUIZ.map((_,i)=>Number(form.get('q'+i))),passed=QUIZ.every((q,i)=>answers[i]===q.answer);if(passed){state.progress.quizPassed=true;lastQuizAnswers=answers;persist('Completed learning: Wallet Safety 101');}$('#quiz-result').innerHTML=`<section class="quiz-result ${passed?'passed':''}"><h3>${passed?'Anda lulus Wallet Safety 101.':'Periksa kembali jawaban Anda.'}</h3>${QUIZ.map((q,i)=>`<p><b>${answers[i]===q.answer?'✓':'○'} ${i+1}.</b> ${q.explanation}</p>`).join('')}${passed?`<p>Misi +50 XP lokal tersedia untuk diklaim di Misi XP.</p><button class="secondary" id="verify-quiz" ${!serverInfo?.rewards||!window.Telegram?.WebApp?.initData?'disabled':''}>Verifikasi pelajaran ke server</button><p class="connection">Verifikasi server memerlukan akun Telegram proyek; XP lokal tidak dikirim sebagai saldo terverifikasi.</p>`:''}</section>`;if(passed)render()});
function applyBlueprint(id){const b=BLUEPRINTS.find(v=>v.id===id);if(!b)return;addProject();const form=$('#new-project');form.elements.name.value=b.title;form.elements.desc.value=b.desc;form.elements.tasks.value=b.tasks.join('\n');if(form.elements.kind)form.elements.kind.value=b.kind;if(form.elements.category)form.elements.category.value=b.category;toast('Lengkapi sumber resmi dan chain, lalu simpan rencana Anda.')}
function badgePage(){const xp=xpTotal(state.progress),info=levelInfo(xp);return xpOverview()+`<div class="section-title"><h2>Koleksi badge</h2><small>${BADGES.filter(b=>badgeEarned(b,state)).length}/${BADGES.length} terbuka</small></div><div class="achievement-grid">${BADGES.map(b=>{const n=b.count(state),earned=badgeEarned(b,state);return `<article class="achievement ${earned?'earned':''}"><span>${icon(b.icon)}</span><h3>${b.name}</h3><p>${b.desc}</p><div class="progress"><span style="width:${earned?100:Math.min(100,n/b.target*100)}%"></span></div><small>${earned?'Terbuka':`${Math.min(n,b.target)}/${b.target} progres`}</small></article>`}).join('')}</div><section class="panel xp-ledger"><h2>Riwayat XP lokal</h2><p>Level ${info.level} menggunakan XP eksplorasi lokal. XP referral server ditampilkan terpisah di Ajak teman.</p>${state.progress.claims.length?`<div class="table-wrap"><table><thead><tr><th>Misi</th><th>XP</th><th>Asal</th></tr></thead><tbody>${[...state.progress.claims].reverse().slice(0,30).map(id=>`<tr><td>${id.startsWith('daily:')?'Riset harian · '+id.slice(6):QUESTS.find(q=>q.id===id)?.title||id}</td><td>+${id.startsWith('daily:')?15:QUESTS.find(q=>q.id===id)?.xp||0}</td><td>Lokal</td></tr>`).join('')}</tbody></table></div>`:empty('Selesaikan misi pertama Anda untuk mulai mengumpulkan XP.')}</section>`}
function currentInvite(){const base=createInvitePayload(location.href);if(remoteXP?.inviteCode){const url=new URL(base.url);url.searchParams.set('ref',remoteXP.inviteCode);return {...base,url:url.href,text:'Jelajahi Airdrop Museum bersama saya. Referral memberi XP aplikasi setelah verifikasi Telegram dan pelajaran keamanan; XP bukan uang atau token.'}}return base}
function inviteSection(){const share=currentInvite(),active=serverInfo?.rewards&&!!window.Telegram?.WebApp?.initData;return `<section class="invite-feature"><div class="invite-feature-art" aria-hidden="true">${icon('share')}<span class="invite-orbit"></span><span class="invite-orbit second"></span></div><div><span class="eyeline">VERIFIED REFERRAL / APP XP</span><h2>Ajak teman.<br>Tumbuh bersama.</h2><p>Referral yang memenuhi syarat memberi <b>100 XP server</b> untuk pengundang. Teman menerima 25 XP sambutan setelah menyelesaikan verifikasi pelajaran 50 XP.</p><div class="referral-rules"><span>1. Masuk melalui Telegram</span><span>2. Gunakan kode sebelum lulus pelajaran</span><span>3. Lulus Wallet Safety 101 di server</span></div><div class="share-field"><label for="invite-url">${remoteXP?'Tautan referral akun Anda':'Tautan umum · belum mengandung kode referral'}</label><div><input id="invite-url" type="url" value="${esc(share.url)}" readonly><button class="secondary" id="copy-invite">Salin</button></div></div><div class="data-actions"><button class="primary" id="share-invite">${icon('share')} Bagikan</button><button class="secondary" id="load-rewards" ${!active||rewardBusy?'disabled':''}>${remoteXP?'Perbarui akun XP':'Aktifkan kode referral'}</button></div><p class="connection">${active?'Kode dan saldo XP server dimuat hanya saat Anda menekan tombol.':'Referral terverifikasi menunggu token bot dan sesi Telegram proyek. Tautan umum belum memberi XP.'}</p></div></section><div class="referral-stats"><div><b>${remoteXP?.xp??'—'}</b><span>XP server terverifikasi</span></div><div><b>${remoteXP?.referrals.total??'—'}</b><span>Referral terikat</span></div><div><b>${remoteXP?.referrals.qualified??'—'}</b><span>Teman memenuhi syarat</span></div></div><section class="panel"><h2>Punya kode dari teman?</h2><p>Kode hanya bisa dikaitkan sekali, sebelum Anda menyelesaikan pelajaran terverifikasi. Kode sendiri ditolak.</p><div class="invite-code-row"><input id="referral-code" value="${esc(pendingInvite)}" maxlength="16" placeholder="Kode referral 16 karakter" aria-label="Kode referral"><button class="secondary" id="bind-invite" ${!active||rewardBusy?'disabled':''}>Gunakan kode</button></div></section><div class="collection-disclosure">${icon('info')}<p>XP tidak dapat ditukar uang atau token. Salin/bagikan tautan tidak memberi XP. Bonus pengundang dibatasi 10 referral memenuhi syarat per hari UTC. Referral tercatat per akun Telegram; pencegahan multi-akun belum setara verifikasi identitas manusia.</p></div>${remoteXP?`<section class="panel xp-ledger"><h2>Ledger XP server</h2>${remoteXP.ledger.length?`<div class="table-wrap"><table><thead><tr><th>Aktivitas</th><th>XP</th><th>Waktu server</th></tr></thead><tbody>${remoteXP.ledger.map(r=>`<tr><td>${esc(r.kind==='referral'?'Referral memenuhi syarat':r.kind==='welcome'?'Bonus sambutan':'Wallet Safety 101')}</td><td>+${r.xp}</td><td>${esc(r.created_at)}</td></tr>`).join('')}</tbody></table></div>`:empty('Belum ada peristiwa XP server.')}</section>`:''}`}
async function rewardRequest(path,body){if(!serverInfo?.rewards||!window.Telegram?.WebApp?.initData)throw Error('Masuk melalui Telegram proyek setelah token bot dikonfigurasi.');const headers={'X-Telegram-Init-Data':window.Telegram.WebApp.initData};const options={headers};if(body!==undefined){headers['Content-Type']='application/json';options.method='POST';options.body=JSON.stringify(body)}const r=await fetch(path,options),data=await r.json();if(!r.ok)throw Error(({REFERRAL_ALREADY_BOUND:'Kode referral sudah terikat.',ALREADY_QUALIFIED:'Referral harus dikaitkan sebelum pelajaran terverifikasi.',INVALID_INVITE:'Kode tidak valid atau milik sendiri.',UNAUTHORIZED:'Sesi Telegram kedaluwarsa. Buka ulang Mini App.'})[data.error]||data.error||'Layanan XP belum tersedia.');return data}
async function loadRewards(){if(rewardBusy)return;rewardBusy=true;try{remoteXP=await rewardRequest('/api/me/rewards');render();toast('Akun XP server berhasil dimuat.')}catch(e){toast(e.message)}finally{rewardBusy=false;render()}}
async function bindInvite(){const code=$('#referral-code')?.value.trim();if(!code)return toast('Masukkan kode referral.');try{await rewardRequest('/api/me/referral',{code});pendingInvite=code;try{sessionStorage.setItem('museum-pending-invite',code)}catch{}toast('Kode terikat. Selesaikan Wallet Safety 101 di server untuk memenuhi syarat.')}catch(e){toast(e.message)}}
async function verifyQuiz(){if(!lastQuizAnswers)return toast('Kerjakan kuis terlebih dahulu.');try{await rewardRequest('/api/me/qualify',{answers:lastQuizAnswers});remoteXP=await rewardRequest('/api/me/rewards');toast('Pelajaran terverifikasi. Peristiwa XP server dicatat satu kali.');render()}catch(e){toast(e.message)}}
function hunterDigest(){const queue=compass(all(),state).filter(c=>c.scheduled>0),proofs=Object.values(state.hunts).reduce((n,h)=>n+h.trail.length,0);return `<section class="hunter-digest"><span class="hunter-digest-icon">${icon('compass')}</span><div><span class="eyeline">BUILT BY MUSEUM / HUNTER COMPASS</span><h3>${queue.length?`${queue.length} langkah riset untuk sesi ${state.hunterProfile.minutes} menit Anda.`:'Ubah peluang menjadi perjalanan riset.'}</h3><p>${queue.length?esc(queue[0].next):'Hunter Lab menghubungkan prioritas, bukti, dan rencana kontribusi dalam satu alur.'} · ${proofs} catatan Proof Trail</p></div><button class="secondary" data-mission-tab="lab">Buka Hunter Lab ${icon('arrow')}</button></section>`}
function hunterLab(){const queue=compass(all(),state),session=queue.filter(q=>q.scheduled>0),totalProofs=Object.values(state.hunts).reduce((n,h)=>n+h.trail.length,0),briefs=Object.values(state.hunts).filter(h=>h.brief.objective).length;return `<section class="hunter-hero"><div><span class="eyeline">MUSEUM ORIGINAL / HUNTER WORKFLOW</span><h2>Dari peluang<br>ke jejak kerja.</h2><p>Hunt Compass → Bounty Brief → Proof Trail → Research Pack. Ruang kerja hunter untuk mengambil langkah yang jelas, menyimpan konteks, dan membawa hasil riset ke mana pun.</p><span class="hunter-signature">Designed for the hunt. Owned by you.</span></div><div class="hunter-system">${[['compass','01','Compass','Tentukan langkah'],['layers','02','Brief','Susun kontribusi'],['shield','03','Proof Trail','Simpan jejak'],['download','04','Research Pack','Bawa hasilnya']].map(([ico,num,title,sub])=>`<div><span>${icon(ico)}</span><small>${num}</small><b>${title}</b><p>${sub}</p></div>`).join('')}</div></section><div class="hunter-metrics"><span><b>${queue.length}</b> exhibit dalam antrean</span><span><b>${session.reduce((n,c)=>n+c.scheduled,0)} menit</b> sesi tersusun</span><span><b>${totalProofs}</b> catatan bukti</span><span><b>${briefs}</b> brief kontribusi</span></div><section class="panel compass-panel"><div class="section-title"><div><span class="eyeline">YOUR RESEARCH SESSION</span><h2>Hunter Compass</h2></div><span class="source-badge personal">Prioritas pribadi · bukan trust score</span></div><form id="compass-form" class="compass-controls"><label>Durasi sesi<select name="minutes">${[15,30,60,120].map(n=>`<option value="${n}" ${state.hunterProfile.minutes===n?'selected':''}>${n} menit</option>`).join('')}</select></label><label>Ekosistem<select name="chain"><option value="All">Semua jaringan</option>${[...new Set(all().map(p=>p.chain))].map(c=>`<option ${state.hunterProfile.chain===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label><label>Fokus<select name="focus">${[['all','Seluruh riset'],['evidence','Lengkapi bukti'],['tasks','Lanjutkan tugas'],['bounty','Brief & bounty']].map(([key,label])=>`<option value="${key}" ${state.hunterProfile.focus===key?'selected':''}>${label}</option>`).join('')}</select></label><button class="primary">Susun sesi ${icon('compass')}</button></form><p class="connection">Urutan berdasarkan status aktif, prioritas pilihan Anda, kedekatan tenggat pribadi, dan kekurangan bukti. Tidak menilai kelayakan investasi atau peluang hadiah.</p>${queue.length?`<div class="compass-queue">${queue.map((c,i)=>`<article class="compass-item ${c.scheduled?'in-session':''}"><span class="compass-position">${String(i+1).padStart(2,'0')}</span><div><div class="compass-item-title"><h3>${esc(c.project.name)}</h3><span>${c.scheduled?c.scheduled+' menit sesi':'Antrean berikutnya'}${c.split?' · dibagi sesi':''}</span></div><p>${esc(c.next)}</p><div class="compass-reasons">${c.reasons.map(t=>`<span>${esc(t)}</span>`).join('')}</div><small>${c.evidence}/5 jenis bukti · ${c.remaining} checklist tersisa · estimasi pribadi ${c.effort} menit</small></div><button class="text-btn" data-hunt-open="${esc(c.project.id)}">Kerjakan ${icon('arrow')}</button></article>`).join('')}</div>`:empty('Belum ada exhibit aktif yang cocok. Simpan exhibit ke portofolio atau ubah fokus sesi.',`<br><button class="text-btn" data-nav="explore">Pilih exhibit ${icon('arrow')}</button>`)}</section><div class="hunter-tool-cards"><section class="panel"><span class="eyeline">PROOF TRAIL</span><h3>Jejak kecil. Konteks yang utuh.</h3><p>Simpan URL sumber, aktivitas, bukti pengiriman, dan hasil dengan catatan serta checkpoint progres saat dicatat. Bandingkan perubahan antarcatatan.</p><button class="secondary" data-proof="select">${icon('plus')} Tambah catatan bukti</button></section><section class="panel"><span class="eyeline">BOUNTY BRIEF</span><h3>Definisikan hasil sebelum bekerja.</h3><p>Tulis tujuan, deliverable, kriteria penerimaan, estimasi sesi dan tautan pengiriman. Checklist kelengkapan membantu meninjau rencana kontribusi.</p><button class="secondary" data-brief="select">${icon('layers')} Susun brief</button></section></div>`}
function hunterExhibit(p){const h=state.hunts[p.id],checks=briefReadiness(p,h),diff=compareProofs(h.trail);return `<section class="hunter-exhibit-intro"><span class="eyeline">PERSONAL HUNTER WORKSPACE</span><h3>Bukti yang punya konteks.</h3><p>Brief dan jejak riset exhibit ini menjadi Research Pack yang dapat Anda ekspor. Semuanya merupakan catatan pribadi, bukan verifikasi independen.</p><div class="data-actions"><button class="primary" data-proof="${esc(p.id)}">${icon('plus')} Catat bukti</button><button class="secondary" data-brief="${esc(p.id)}">Edit brief</button><button class="secondary" data-pack="${esc(p.id)}">${icon('download')} Research Pack</button></div></section><section class="brief-overview"><div class="section-title"><h3>Bounty Brief</h3><span class="source-badge personal">${BRIEF_STAGES[h.brief.stage]}</span></div><p>${esc(h.brief.objective||'Belum ada tujuan kontribusi. Susun brief untuk menentukan apa yang ingin Anda hasilkan.')}</p>${h.brief.deliverables.length?`<ol>${h.brief.deliverables.map(v=>`<li>${esc(v)}</li>`).join('')}</ol>`:''}<div class="brief-readiness">${checks.map(c=>`<span class="${c.done?'ready':''}">${icon(c.done?'check':'info')}${c.label}</span>`).join('')}</div><small>${checks.filter(c=>c.done).length}/6 bagian lengkap · kelengkapan pribadi, bukan persetujuan program.</small></section><section class="proof-trail"><div class="section-title"><h3>Proof Trail</h3><small>${h.trail.length}/30 catatan</small></div>${h.trail.length?`<div class="proof-timeline">${[...h.trail].reverse().map(e=>`<article><span class="proof-timeline-dot"></span><div class="proof-meta"><b>${PROOF_TYPES[e.kind]}</b><time>${esc(new Date(e.at).toLocaleString('id-ID'))}</time></div><h4>${esc(e.label)}</h4><p>${esc(e.note||'Tanpa anotasi.')}</p>${e.url?`<code>${esc(e.url)}</code>`:''}<small>Checkpoint lokal: ${e.snapshot.tasksDone} tugas · ${e.snapshot.evidenceCount} jenis bukti dossier</small></article>`).join('')}</div>`:empty('Belum ada bukti dicatat. Mulai dari sumber resmi dan aturan program.')}</section>${h.trail.length>=2?`<section class="checkpoint-diff"><h3>Perubahan checkpoint pertama → terakhir</h3>${diff.length?diff.map(d=>`<div><span>${d.label}</span><b>${esc(d.before)} ${icon('arrow')} ${esc(d.after)}</b></div>`).join(''):'<p>Belum ada perubahan pada lima indikator progres yang dicatat.</p>'}</section>`:''}<div class="collection-disclosure">${icon('lock')}<p>Proof Trail tersimpan lokal dan dapat ikut backup. Waktu dicatat dari perangkat; bukan timestamp blockchain atau bukti yang tidak dapat diubah. Tinjau informasi pribadi sebelum membagikan Research Pack.</p></div>`}
function hunterDialog(){if(!$('#hunter-dialog'))document.body.insertAdjacentHTML('beforeend','<dialog id="hunter-dialog"></dialog>');return $('#hunter-dialog')}
function projectSelect(id){return `<label>Exhibit<select name="projectId" id="hunter-project" required>${all().map(p=>`<option value="${esc(p.id)}" ${p.id===id?'selected':''}>${esc(p.name)}${p.custom?'':' · contoh fiktif'}</option>`).join('')}</select></label>`}
function openProof(id){const p=project(id)||all().find(p=>state.saved.includes(p.id))||all()[0];if(!p)return toast('Tambahkan exhibit terlebih dahulu.');const dialog=hunterDialog();dialog.innerHTML=`<div class="detail-body"><div class="section-title"><div><span class="eyeline">MUSEUM ORIGINAL / PROOF TRAIL</span><h2>Catat jejak riset.</h2></div><button class="icon-button" id="close-hunter" aria-label="Tutup">${icon('close')}</button></div><p>Simpan konteks sumber atau pekerjaan, bukan sekadar tautan. Jangan menyimpan token, private key, seed phrase, atau URL rahasia.</p><form id="proof-form">${projectSelect(p.id)}<label>Jenis bukti<select name="kind">${Object.entries(PROOF_TYPES).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label>Judul singkat<input name="label" minlength="3" maxlength="80" required placeholder="Aturan snapshot ditinjau"></label><label>URL sumber / bukti<input type="url" name="url" maxlength="500" placeholder="https://…"></label><label>Apa yang ditemukan atau dikerjakan?<textarea name="note" rows="4" minlength="20" maxlength="600" required placeholder="Sebutkan konteks, temuan, dan batas informasi yang masih belum pasti."></textarea></label><button class="primary">Simpan Proof Trail ${icon('check')}</button></form></div>`;dialog.showModal()}
function openBrief(id){const p=project(id)||all().find(p=>state.saved.includes(p.id))||all()[0];if(!p)return toast('Tambahkan exhibit terlebih dahulu.');const b=state.hunts[p.id].brief,dialog=hunterDialog();dialog.innerHTML=`<div class="detail-body"><div class="section-title"><div><span class="eyeline">MUSEUM ORIGINAL / BOUNTY BRIEF</span><h2>Rencanakan kontribusi.</h2></div><button class="icon-button" id="close-hunter" aria-label="Tutup">${icon('close')}</button></div><form id="brief-form">${projectSelect(p.id)}<label>Tujuan kontribusi<textarea name="objective" rows="3" maxlength="600" required minlength="15">${esc(b.objective)}</textarea></label><label>Deliverable · satu per baris<textarea name="deliverables" rows="4" maxlength="1800" required placeholder="Tutorial dengan langkah reproduksi\nRingkasan temuan dengan bukti">${esc(b.deliverables.join('\n'))}</textarea></label><label>Kriteria penerimaan / aturan yang dirujuk<textarea name="acceptance" rows="3" maxlength="600" required minlength="15">${esc(b.acceptance)}</textarea></label><div class="form-grid"><label>Estimasi sesi pribadi<select name="effort">${[15,30,60,120].map(n=>`<option value="${n}" ${b.effort===n?'selected':''}>${n} menit</option>`).join('')}</select></label><label>Status kontribusi<select name="stage">${Object.entries(BRIEF_STAGES).map(([key,label])=>`<option value="${key}" ${b.stage===key?'selected':''}>${label}</option>`).join('')}</select></label></div><label>URL pengiriman · opsional<input type="url" name="submissionURL" maxlength="500" value="${esc(b.submissionURL)}" placeholder="https://…"></label><p class="connection">Mengubah status tidak mengirim pekerjaan ke pihak lain dan tidak membuktikan bahwa program telah menerimanya.</p><button class="primary">Simpan Bounty Brief ${icon('check')}</button></form></div>`;dialog.showModal()}
document.addEventListener('change',e=>{if(e.target.id==='hunter-project'&&e.target.closest('#brief-form')){const b=state.hunts[e.target.value]?.brief;if(!b)return;const f=e.target.form;f.elements.objective.value=b.objective;f.elements.deliverables.value=b.deliverables.join('\n');f.elements.acceptance.value=b.acceptance;f.elements.effort.value=b.effort;f.elements.stage.value=b.stage;f.elements.submissionURL.value=b.submissionURL}});
document.addEventListener('submit',e=>{if(!['proof-form','brief-form','compass-form'].includes(e.target.id))return;e.preventDefault();const data=Object.fromEntries(new FormData(e.target));try{if(e.target.id==='compass-form'){state.hunterProfile=cleanHunterProfile(data);persist('Updated hunter session');render();toast('Sesi riset disusun dari catatan Anda.');return}const p=project(data.projectId);if(!p)throw Error('Exhibit tidak ditemukan.');if(e.target.id==='proof-form'){state.hunts[p.id]=addProof(state,p,data);persist('Saved proof trail: '+p.name)}else{state.hunts[p.id].brief=cleanBrief({...data,deliverables:data.deliverables.split('\n')});persist('Saved bounty brief: '+p.name)}if(!state.saved.includes(p.id))state.saved.push(p.id);persist();$('#hunter-dialog').close();render();if(openId!==p.id){openId=p.id;detailDraft=null}detailTab='lab';showDetail(p.id);toast('Catatan hunter tersimpan.')}catch(err){let feedback=e.target.querySelector('.form-error');if(!feedback){feedback=document.createElement('p');feedback.className='notice form-error';feedback.setAttribute('role','alert');e.target.append(feedback)}feedback.textContent=err.message}});

// Blueprint stage: personal campaign intelligence and in-app deadline radar.
function directoryFilterUI(){return `<details class="advanced-filters" open><summary>${icon('list')} Filter peluang</summary><div class="advanced-filter-grid"><label>Status kampanye<select data-directory="status">${[['all','Semua status'],...Object.entries(CAMPAIGN_STATUS)].map(([key,label])=>`<option value="${key}" ${directoryFilters.status===key?'selected':''}>${label}</option>`).join('')}</select></label><label>Jenis peluang<select data-directory="kind">${[['all','Semua jenis'],['airdrop','Airdrop'],['testnet','Testnet'],['bounty','Bounty'],['community','Kontribusi komunitas']].map(([key,label])=>`<option value="${key}" ${directoryFilters.kind===key?'selected':''}>${label}</option>`).join('')}</select></label><label>Kesulitan pribadi<select data-directory="difficulty">${[['all','Semua tingkat'],['unknown','Belum dinilai'],['beginner','Pemula'],['intermediate','Menengah'],['advanced','Lanjutan']].map(([key,label])=>`<option value="${key}" ${directoryFilters.difficulty===key?'selected':''}>${label}</option>`).join('')}</select></label><label>Estimasi gas pribadi<select data-directory="cost">${[['all','Semua biaya'],['unknown','Belum dicatat'],['zero','Dicatat $0'],['low','Dicatat ≤ $5']].map(([key,label])=>`<option value="${key}" ${directoryFilters.cost===key?'selected':''}>${label}</option>`).join('')}</select></label></div><p>Status dan estimasi diisi sendiri berdasarkan sumber; belum diverifikasi Museum. Biaya aktual dapat berubah.</p></details>`}
function campaignCard(p){const c=state.campaigns[p.id];return `<div class="campaign-card-meta"><span class="campaign-status campaign-${c.status}">${CAMPAIGN_STATUS[c.status]}</span>${c.deadline?`<span>${icon('calendar')}${esc(c.deadline)}</span>`:''}${c.gasUSD!==null?`<span>Est. gas ${money(c.gasUSD)}</span>`:''}</div>`}
function campaignOverview(p){const c=state.campaigns[p.id];return `<section class="campaign-overview"><div class="section-title"><div><span class="eyeline">CAMPAIGN INTELLIGENCE / PERSONAL</span><h3>Aturan, waktu & konteks.</h3></div><button class="text-btn" data-campaign="${esc(p.id)}">${icon('plus')} Ubah data</button></div><div class="campaign-facts"><div><small>Status dari sumber</small><b>${CAMPAIGN_STATUS[c.status]}</b></div><div><small>Tenggat kampanye</small><b>${esc(c.deadline||'Belum dicatat')}</b></div><div><small>Tanggal snapshot</small><b>${esc(c.snapshot||'Belum dicatat')}</b></div><div><small>Estimasi gas pribadi</small><b>${c.gasUSD===null?'Belum dicatat':money(c.gasUSD)}</b></div></div><p class="campaign-requirements">${esc(c.requirements||'Catat syarat program, tanggal, dan sumber pengumuman sebelum memulai partisipasi.')}</p><dl class="campaign-links">${[['Pengumuman / aturan',c.source],['Explorer kontrak',c.contract],['Kanal komunitas',c.channel]].map(([label,url])=>`<div><dt>${label}</dt><dd>${url?`<code>${esc(url)}</code>`:'Belum dicatat'}</dd></div>`).join('')}</dl>${c.reward?`<p>Catatan reward: ${esc(c.reward)}</p>`:''}<div class="campaign-bottom"><span>${icon('info')} Catatan pemilik · belum diverifikasi${c.checkedAt?' · ditinjau '+esc(c.checkedAt):''}</span><button class="secondary" data-campaign-calendar="${esc(p.id)}">${icon('download')} Kalender kampanye</button></div>${c.changes.length?`<details class="campaign-changes"><summary>Riwayat perubahan · ${c.changes.length}</summary>${[...c.changes].reverse().map(e=>`<div><time>${esc(new Date(e.at).toLocaleString('id-ID'))}</time><p>${esc(e.summary)}</p></div>`).join('')}</details>`:''}</section>`}
function openCampaign(id){const p=project(id);if(!p)return;const c=state.campaigns[p.id],dialog=hunterDialog();dialog.innerHTML=`<div class="detail-body"><div class="section-title"><div><span class="eyeline">CAMPAIGN INTELLIGENCE</span><h2>Catat aturan kampanye.</h2></div><button class="icon-button" id="close-hunter" aria-label="Tutup">${icon('close')}</button></div><p>${esc(p.name)} · data ini pribadi. Status “Diumumkan” atau “Berlangsung” bukan pengesahan oleh Museum.</p><form id="campaign-form" data-project="${esc(p.id)}"><label>URL pengumuman / aturan<input name="source" type="url" maxlength="500" placeholder="https://…" value="${esc(c.source)}"></label><div class="form-grid"><label>Status dari sumber<select name="status">${Object.entries(CAMPAIGN_STATUS).map(([key,label])=>`<option value="${key}" ${c.status===key?'selected':''}>${label}</option>`).join('')}</select></label><label>Kesulitan pribadi<select name="difficulty">${[['unknown','Belum dinilai'],['beginner','Pemula'],['intermediate','Menengah'],['advanced','Lanjutan']].map(([key,label])=>`<option value="${key}" ${c.difficulty===key?'selected':''}>${label}</option>`).join('')}</select></label><label>Tenggat kampanye<input name="deadline" type="date" value="${esc(c.deadline)}"></label><label>Tanggal snapshot<input name="snapshot" type="date" value="${esc(c.snapshot)}"></label><label>Estimasi gas · USD<input name="gasUSD" type="number" min="0" max="1000000" step="0.01" placeholder="Belum diketahui" value="${c.gasUSD??''}"></label><label>Tanggal tinjauan pribadi<input name="checkedAt" type="date" value="${esc(c.checkedAt)}"></label></div><label>Syarat & batas program<textarea name="requirements" maxlength="1000" rows="4">${esc(c.requirements)}</textarea></label><label>Catatan reward · tanpa asumsi nilai<input name="reward" maxlength="200" value="${esc(c.reward)}" placeholder="Belum diumumkan / ketentuan dari sumber"></label><label>URL explorer kontrak<input name="contract" type="url" maxlength="500" value="${esc(c.contract)}"></label><label>URL kanal komunitas<input name="channel" type="url" maxlength="500" value="${esc(c.channel)}"></label><p class="connection">Tanggal bersifat tanggal kalender, tanpa asumsi jam atau zona waktu penutupan. Periksa sumber resmi. Perubahan disimpan sebagai riwayat lokal.</p><button class="primary">Simpan data kampanye ${icon('check')}</button></form></div>`;dialog.showModal()}
function refreshRadarButton(){if(!$('#open-radar'))$('#profile-top').insertAdjacentHTML('beforebegin','<button class="radar-header-button" id="open-radar" data-mission-tab="radar"></button>');const unread=radarEvents(all(),state).filter(e=>!e.read).length;$('#open-radar').innerHTML=`${icon('calendar')}${unread?`<b>${unread}</b>`:''}`;$('#open-radar').setAttribute('aria-label',`Buka Radar · ${unread} pengingat belum dibaca`)}
function radarDigest(){const events=radarEvents(all(),state);return events.length?`<section class="radar-digest"><span>${icon('calendar')}</span><div><b>${events.length} tanggal memerlukan perhatian.</b><p>${events.filter(e=>!e.read).length} belum dibaca · snapshot, tenggat kampanye, dan target pribadi.</p></div><button class="secondary" data-mission-tab="radar">Buka Radar ${icon('arrow')}</button></section>`:''}
function radarPage(){const events=radarEvents(all(),state),unread=events.filter(e=>!e.read).length;return `<section class="radar-hero"><div><span class="eyeline">MUSEUM RADAR / IN-APP REMINDERS</span><h2>Jangan kehilangan<br>momen penting.</h2><p>Snapshot, tenggat kampanye dan target riset Anda dalam satu antrean. Dihitung dari tanggal yang Anda simpan saat aplikasi dibuka.</p></div><div class="radar-signal" aria-hidden="true"><span></span><i></i><b>${unread}</b><small>BELUM DIBACA</small></div></section><div class="hunter-metrics radar-metrics"><span><b>${events.filter(e=>e.kind==='snapshot').length}</b> snapshot</span><span><b>${events.filter(e=>e.kind==='deadline').length}</b> tenggat kampanye</span><span><b>${events.filter(e=>e.kind==='personal').length}</b> target pribadi</span><span><b>${events.filter(e=>e.days<0).length}</b> tanggal terlewat</span></div><section class="panel"><div class="section-title"><div><span class="eyeline">NEXT 7 DAYS / PAST 30 DAYS</span><h2>Pusat perhatian</h2></div><button class="text-btn" id="radar-read-all" ${!unread?'disabled':''}>Tandai semua dibaca ${icon('check')}</button></div>${events.length?events.map(e=>`<article class="radar-event ${e.read?'is-read':''}"><div class="radar-date"><b>${Number(e.date.slice(-2))}</b><span>${esc(new Date(e.date+'T12:00:00').toLocaleDateString('id-ID',{month:'short'}))}</span></div><div class="radar-event-copy"><span class="eyeline">${e.label}</span><h3>${esc(e.project.name)}</h3><p>${e.days<0?Math.abs(e.days)+' hari terlewat':e.days===0?'Hari ini':e.days+' hari lagi'} · ${esc(e.date)} · ${e.project.custom?'Proyek pribadi':'Contoh fiktif'}</p>${e.source?`<code>${esc(e.source)}</code>`:''}<small>${e.read?'Sudah dibaca':'Belum dibaca'} · bukan konfirmasi snapshot atau eligibility</small></div><div class="radar-actions"><button class="secondary" data-open="${esc(e.project.id)}">Tinjau exhibit ${icon('arrow')}</button>${!e.read?`<button class="text-btn" data-radar-read="${esc(e.id)}">Tandai dibaca</button>`:''}</div></article>`).join(''):`<div class="radar-empty">${icon('calendar')}<h3>Belum ada tanggal yang mendekat.</h3><p>Simpan exhibit, lalu isi tanggal snapshot atau tenggat di Ringkasan & bukti → Ubah data. Target pribadi dapat diatur di Tugas & catatan.</p><button class="primary" data-nav="explore">Pilih exhibit ${icon('arrow')}</button></div>`}</section><div class="collection-disclosure">${icon('info')}<p>Radar hanya menampilkan exhibit di portofolio yang belum selesai/diarsipkan. Belum mengirim push, email atau pesan Telegram. Tanggal dari sumber tetap harus diperiksa kembali; tandai dibaca tidak mengubah status tugas.</p></div>`}
document.addEventListener('change',e=>{if(e.target.dataset.directory){directoryFilters[e.target.dataset.directory]=e.target.value;updateGrid()}if(e.target.dataset.taskState){const key=e.target.dataset.taskState,value=e.target.value;if(!Object.hasOwn(TASK_STATUS,value))return;const p=project(openId);if(!p||!p.tasks.some((_,i)=>key===p.id+':'+i))return;const form=$('#record-form');if(form){const data=Object.fromEntries(new FormData(form));state.records[p.id]={...state.records[p.id],...data,dossier:cleanDossier(data)};detailDraft=null}state.taskStates[key]=value;state.done[key]=value==='done';if(!state.saved.includes(p.id))state.saved.push(p.id);state=normalize(state,demos);persist('Updated checklist: '+p.name);render();showDetail(p.id)}});
document.addEventListener('submit',e=>{if(e.target.id!=='campaign-form')return;e.preventDefault();const p=project(e.target.dataset.project);if(!p)return;try{state.campaigns[p.id]=updateCampaign(state.campaigns[p.id],Object.fromEntries(new FormData(e.target)));if(!state.saved.includes(p.id))state.saved.push(p.id);persist('Saved research: campaign '+p.name);$('#hunter-dialog').close();render();if(openId!==p.id)detailDraft=null;openId=p.id;detailTab='overview';showDetail(p.id);toast('Data kampanye dan riwayat tersimpan.')}catch(err){let feedback=e.target.querySelector('.form-error');if(!feedback){feedback=document.createElement('p');feedback.className='notice form-error';feedback.setAttribute('role','alert');e.target.append(feedback)}feedback.textContent=err.message}});
